//go:build http

package httpserver

// Godog harness for features/config_schema_comments.feature: drives the settings
// screen's read-modify-write cycle (GET /coddy/config, PUT /coddy/config) against a
// gateway whose config.yaml carries hand-written comments, and inspects the file that
// lands on disk.

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/cucumber/godog"

	"github.com/EvilFreelancer/coddy-agent/internal/acp"
	"github.com/EvilFreelancer/coddy-agent/internal/config"
	"github.com/EvilFreelancer/coddy-agent/internal/session"
)

// commentedConfigYAML is a config an operator wrote by hand: a header block, a comment
// above a provider, an inline note, and a commented-out key inside the provider entry.
const commentedConfigYAML = `# yaml-language-server: $schema=https://coddy.dev/config.schema.json
# Workstation setup - the vault fills the keys in.

providers:
  # the llama.cpp box in the basement
  - name: valera
    type: openai
    # api_key_command: "vault read -field=key coddy/valera"
    api_key: "k" # rotated every friday
models:
  - model: valera/qwen3.8-27b
    max_tokens: 4096
agent:
  model: valera/qwen3.8-27b
`

// bareConfigYAML has no comments at all, the state a config generated by the settings
// screen is in before this feature existed.
const bareConfigYAML = `providers:
  - name: valera
    type: openai
    api_key: "k"
models:
  - model: valera/qwen3.8-27b
    max_tokens: 4096
agent:
  model: valera/qwen3.8-27b
`

type configCommentsWorld struct {
	ts      *httptest.Server
	cfgPath string
	initial string
	saved   string
}

func (w *configCommentsWorld) startGateway(t *testing.T, yml string) error {
	home := t.TempDir()
	w.cfgPath = filepath.Join(home, "config.yaml")
	w.initial = yml
	if err := os.WriteFile(w.cfgPath, []byte(yml), 0o644); err != nil {
		return err
	}
	cfg, err := config.Load(w.cfgPath)
	if err != nil {
		return err
	}
	runner := func(context.Context, *session.State, []acp.ContentBlock, acp.UpdateSender) (string, error) {
		return string(acp.StopReasonEndTurn), nil
	}
	mgr := session.NewManager(cfg, noopSender{}, runner, slog.Default(), home, nil)
	srv := New(cfg, mgr, slog.Default(), home)
	w.ts = httptest.NewServer(srv.Handler())
	t.Cleanup(w.ts.Close)
	return nil
}

// saveWithAgentField mirrors what the settings screen does: read the config document,
// change one field in it, and write the whole document back.
func (w *configCommentsWorld) saveWithAgentField(field string, value int) error {
	if w.ts == nil {
		return fmt.Errorf("gateway not started")
	}
	res, err := http.Get(w.ts.URL + "/coddy/config")
	if err != nil {
		return err
	}
	defer func() { _ = res.Body.Close() }()
	if res.StatusCode != http.StatusOK {
		return fmt.Errorf("GET /coddy/config: status %d, want 200", res.StatusCode)
	}
	var doc map[string]interface{}
	if err := json.NewDecoder(res.Body).Decode(&doc); err != nil {
		return err
	}
	section, key, ok := strings.Cut(field, ".")
	if !ok {
		return fmt.Errorf("field %q must be section.key", field)
	}
	obj, _ := doc[section].(map[string]interface{})
	if obj == nil {
		obj = map[string]interface{}{}
		doc[section] = obj
	}
	obj[key] = value

	body, err := json.Marshal(doc)
	if err != nil {
		return err
	}
	req, err := http.NewRequest(http.MethodPut, w.ts.URL+"/coddy/config", bytes.NewReader(body))
	if err != nil {
		return err
	}
	req.Header.Set("Content-Type", "application/json")
	put, err := http.DefaultClient.Do(req)
	if err != nil {
		return err
	}
	defer func() { _ = put.Body.Close() }()
	if put.StatusCode != http.StatusOK {
		raw, _ := readAllString(put)
		return fmt.Errorf("PUT /coddy/config: status %d, want 200 (%s)", put.StatusCode, raw)
	}
	raw, err := os.ReadFile(w.cfgPath)
	if err != nil {
		return err
	}
	w.saved = string(raw)
	return nil
}

func readAllString(res *http.Response) (string, error) {
	var buf bytes.Buffer
	if _, err := buf.ReadFrom(res.Body); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func (w *configCommentsWorld) wantOperatorComments() error {
	for _, want := range []string{
		"# Workstation setup - the vault fills the keys in.",
		"# the llama.cpp box in the basement",
		`# api_key_command: "vault read -field=key coddy/valera"`,
		"# rotated every friday",
	} {
		if !strings.Contains(w.saved, want) {
			return fmt.Errorf("saved config lost the comment %q:\n%s", want, w.saved)
		}
	}
	return nil
}

func (w *configCommentsWorld) wantAgentField(field string, value int) error {
	_, key, ok := strings.Cut(field, ".")
	if !ok {
		return fmt.Errorf("field %q must be section.key", field)
	}
	want := fmt.Sprintf("%s: %d", key, value)
	if !strings.Contains(w.saved, want) {
		return fmt.Errorf("saved config does not carry %q:\n%s", want, w.saved)
	}
	return nil
}

// blankLines counts the lines a reader sees as empty, whatever an editor ended them with.
func blankLines(body string) int {
	n := 0
	for _, line := range strings.Split(strings.ReplaceAll(body, "\r\n", "\n"), "\n") {
		if strings.TrimSpace(line) == "" {
			n++
		}
	}
	return n
}

func (w *configCommentsWorld) wantNoNewBlankLines() error {
	if got, want := blankLines(w.saved), blankLines(w.initial); got != want {
		return fmt.Errorf("the save turned %d blank lines into %d:\n%s", want, got, w.saved)
	}
	return nil
}

func (w *configCommentsWorld) wantWindowsLineEndings() error {
	if strings.Count(w.saved, "\n") != strings.Count(w.saved, "\r\n") {
		return fmt.Errorf("the save mixed Windows and Unix line endings:\n%q", w.saved)
	}
	return nil
}

func (w *configCommentsWorld) wantSchemaHeader(url string) error {
	want := "# yaml-language-server: $schema=" + url
	first, _, _ := strings.Cut(w.saved, "\n")
	if strings.TrimSpace(first) != want {
		return fmt.Errorf("saved config starts with %q, want %q", first, want)
	}
	return nil
}

func (w *configCommentsWorld) wantSchemaReference(ref string) error {
	if !strings.Contains(w.saved, "$schema="+ref) {
		return fmt.Errorf("saved config no longer points at %q:\n%s", ref, w.saved)
	}
	return nil
}

func (w *configCommentsWorld) wantSingleSchemaHeader() error {
	if got := strings.Count(w.saved, "yaml-language-server:"); got != 1 {
		return fmt.Errorf("saved config carries %d schema headers, want 1:\n%s", got, w.saved)
	}
	return nil
}

func TestConfigSchemaCommentsFeature(t *testing.T) {
	suite := godog.TestSuite{
		Name: "config_schema_comments",
		ScenarioInitializer: func(sc *godog.ScenarioContext) {
			w := &configCommentsWorld{}
			sc.Step(`^a coddy server whose config\.yaml carries operator comments$`, func() error {
				return w.startGateway(t, commentedConfigYAML)
			})
			sc.Step(`^a coddy server whose config\.yaml carries operator comments in Windows text$`, func() error {
				return w.startGateway(t, strings.ReplaceAll(commentedConfigYAML, "\n", "\r\n"))
			})
			sc.Step(`^a coddy server whose config\.yaml has no schema header$`, func() error {
				return w.startGateway(t, bareConfigYAML)
			})
			sc.Step(`^a coddy server whose config\.yaml points its editor at "([^"]*)"$`, func(ref string) error {
				return w.startGateway(t, "# yaml-language-server: $schema="+ref+"\n"+bareConfigYAML)
			})
			sc.Step(`^the settings screen saves the config with "([^"]*)" set to (\d+)$`, w.saveWithAgentField)
			sc.Step(`^the saved config\.yaml still carries the operator comments$`, w.wantOperatorComments)
			sc.Step(`^the saved config\.yaml sets "([^"]*)" to (\d+)$`, w.wantAgentField)
			sc.Step(`^the saved config\.yaml gained no blank lines$`, w.wantNoNewBlankLines)
			sc.Step(`^the saved config\.yaml still ends its lines the Windows way$`, w.wantWindowsLineEndings)
			sc.Step(`^the saved config\.yaml starts with the schema header for "([^"]*)"$`, w.wantSchemaHeader)
			sc.Step(`^the saved config\.yaml still points its editor at "([^"]*)"$`, w.wantSchemaReference)
			sc.Step(`^the saved config\.yaml carries exactly one schema header$`, w.wantSingleSchemaHeader)
		},
		Options: &godog.Options{
			Format:   "pretty",
			Paths:    []string{"../../features/config_schema_comments.feature"},
			TestingT: t,
		},
	}
	if suite.Run() != 0 {
		t.Fatal("config_schema_comments feature failed")
	}
}
